on conflict (username) do update set old_uid = excluded.old_uid, docs = excluded.docs where public.seed_import.claimed_at is null;

-- 샘플 도구 13개 (다음 주 실제 도구가 들어오면 정리 예정)
on conflict (col, id) do nothing;
